(function(){
'use strict';
const button=document.getElementById('offlineButton'),status=document.getElementById('offlineStatus'),install=document.getElementById('installButton');let registration=null,prompt=null,ready=false,busy=false;
function say(message){status.textContent=message;}
document.getElementById('offlineReload').onclick=()=>location.reload();
fetch('offline-package.json').then(r=>r.json()).then(m=>{document.getElementById('offlineSize').textContent='Təxminən '+Math.ceil(m.bytes/1024/1024)+' MB · sözlük, xəritə, oyun və qrammatika';}).catch(()=>{});
function send(worker,type){return new Promise((resolve,reject)=>{const channel=new MessageChannel();let timeout;const arm=()=>{clearTimeout(timeout);timeout=setTimeout(()=>{channel.port1.close();reject(new Error('Bağlantı vaxtı bitdi. Yenidən cəhd edin.'));},180000);};arm();channel.port1.onmessage=e=>{const d=e.data;if(d.progress!==undefined){arm();say('Cihazda saxlanılır: '+d.progress+'%');return;}clearTimeout(timeout);channel.port1.close();if(d.error)reject(new Error(d.error));else resolve(d);};worker.postMessage({type},[channel.port2]);});}
async function currentWorker(){
 await registration.update();const pending=registration.installing||registration.waiting;
 if(pending&&pending.state!=='activated'&&pending.state!=='redundant')await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{pending.removeEventListener('statechange',changed);reject(new Error('Yeniləmə tamamlanmadı. Səhifəni yeniləyin.'));},30000);function changed(){if(pending.state==='activated'){clearTimeout(timeout);pending.removeEventListener('statechange',changed);resolve();}else if(pending.state==='redundant'){clearTimeout(timeout);pending.removeEventListener('statechange',changed);reject(new Error('Yeniləmə alınmadı. Yenidən cəhd edin.'));}}pending.addEventListener('statechange',changed);changed();});
 await navigator.serviceWorker.ready;return registration.active;
}
async function check(){if(!registration?.active)return;const result=await send(registration.active,'STATUS');ready=!!result.ready;if(ready&&!result.current)document.getElementById('offlineReload').hidden=false;say(ready?(result.current?'Oflayn istifadə hazırdır.':'Yeni versiya mövcuddur. Oflayn məlumatı yeniləyin.'):'İlk yükləmə üçün internet lazımdır.');button.textContent=ready?'Oflayn məlumatı yenilə':'Oflayn istifadə üçün yüklə';}
button.onclick=async()=>{if(busy)return;busy=true;button.disabled=true;try{if(!registration)throw new Error('Oflayn qeydiyyat hazır deyil. Bir az sonra yenidən cəhd edin.');const worker=await currentWorker();if(!worker)throw new Error('Səhifəni yeniləyib yenidən cəhd edin.');const result=await send(worker,'CACHE_APP');ready=!!result.ready;if(!ready)throw new Error('Yükləmə tamamlanmadı.');say('Oflayn istifadə hazırdır. Təyyarə rejimində yenidən aça bilərsiniz.');button.textContent='Oflayn məlumatı yenilə';document.getElementById('offlineReload').hidden=false;try{await navigator.storage?.persist?.();}catch{}}catch(e){say('Oflayn yükləmə tamamlanmadı. '+e.message);}finally{busy=false;button.disabled=false;}};
function refreshRegistration(){if(registration&&!busy)registration.update().then(check).catch(()=>{});}
window.addEventListener('pageshow',refreshRegistration);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshRegistration();});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async reg=>{registration=reg;await navigator.serviceWorker.ready;await check();navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!busy)check().catch(()=>{});});}).catch(()=>say('Bu brauzerdə oflayn quraşdırma mümkün olmadı.'));else{button.disabled=true;say('Bu brauzer oflayn quraşdırmanı dəstəkləmir.');}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e;install.hidden=false;});install.onclick=async()=>{if(prompt){await prompt.prompt();await prompt.userChoice;prompt=null;install.hidden=true;}};window.addEventListener('appinstalled',()=>{install.hidden=true;say(ready?'SÖZ quraşdırıldı. Oflayn istifadə hazırdır.':'SÖZ quraşdırıldı. Oflayn istifadə üçün məlumatı yükləyin.');});
})();
